script:
const root = root_element.querySelector('.clinify-saas-dashboard');

root.innerHTML = `<div class="clinify-saas-loading">Loading SaaS Dashboard…</div>`;

frappe.call({
    method: 'clinify.clinify.page.saas_dashboard.saas_dashboard.get_dashboard'
}).then((r) => {
    const data = r.message || {};
    const metrics = data.metrics || {};
    const tenants = data.recent_tenants || [];

    const esc = (value) => frappe.utils.escape_html(value == null ? '' : String(value));

    const metric = (label, value) => `
        <div class="clinify-saas-metric">
            <div class="clinify-saas-metric-label">${esc(label)}</div>
            <div class="clinify-saas-metric-value">${esc(value)}</div>
        </div>`;

    const rows = tenants.length
        ? tenants.map((tenant) => `
            <tr data-tenant="${esc(tenant.name)}">
                <td>${esc(tenant.tenant_name || '—')}</td>
                <td>${esc(tenant.tenant_id || '—')}</td>
                <td>${esc(tenant.plan || '—')}</td>
                <td>${esc(tenant.clinic_status || '—')}</td>
                <td>${esc(tenant.subscription_status || '—')}</td>
                <td>${esc(tenant.subscription_end_date || '—')}</td>
            </tr>`).join('')
        : `<tr><td colspan="6" class="clinify-saas-empty">No tenant accounts found.</td></tr>`;

    root.innerHTML = `
        <div class="clinify-saas-header">
            <div>
                <h2>SaaS Dashboard</h2>
                <p>Clinify platform administration</p>
            </div>
        </div>

        <div class="clinify-saas-metrics">
            ${metric('Total Clinics', metrics.total_clinics)}
            ${metric('Active Clinics', metrics.active_clinics)}
            ${metric('Active Subscriptions', metrics.active_subscriptions)}
            ${metric('Trial Subscriptions', metrics.trial_subscriptions)}
            ${metric('Expiring Within 30 Days', metrics.expiring_30_days)}
            ${metric('Provisioning Pending', metrics.provisioning_pending)}
            ${metric('Provisioning Failed', metrics.provisioning_failed)}
        </div>

        <div class="clinify-saas-section">
            <div class="clinify-saas-section-title">Tenant Management</div>
            <div class="clinify-saas-actions">
                <button class="btn btn-primary btn-sm" data-action="tenants">Tenant Accounts</button>
                <button class="btn btn-default btn-sm" data-action="create">Create Tenant</button>
                <button class="btn btn-default btn-sm" data-action="subscriptions">Subscriptions &amp; Plans</button>
            </div>
        </div>

        <div class="clinify-saas-section">
            <div class="clinify-saas-section-title">Tenant Overview</div>
            <div class="clinify-saas-table-wrap">
                <table class="clinify-saas-table">
                    <thead>
                        <tr>
                            <th>Clinic</th>
                            <th>Tenant ID</th>
                            <th>Plan</th>
                            <th>Status</th>
                            <th>Subscription</th>
                            <th>Valid Until</th>
                        </tr>
                    </thead>
                    <tbody>${rows}</tbody>
                </table>
            </div>
        </div>`;

    root.querySelector('[data-action="tenants"]').onclick = () =>
        frappe.set_route('List', 'Clinify Tenant');

    root.querySelector('[data-action="create"]').onclick = () =>
        frappe.new_doc('Clinify Tenant');

    root.querySelector('[data-action="subscriptions"]').onclick = () =>
        frappe.set_route('List', 'Clinify Subscription');

    root.querySelectorAll('tr[data-tenant]').forEach((row) => {
        row.onclick = () => frappe.set_route('Form', 'Clinify Tenant', row.dataset.tenant);
    });
});
